import{_ as t,a0 as p,w as o,s as d,ao as c,I as l,x as e,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"一套有用的 Unix 實用程序 | LCTT x X-CMD","titleTemplate":false,"description":"一套有用的 Unix 實用程序 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一套有用的 Unix 實用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一套有用的 Unix 實用程序 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180821 A Collection Of More Useful Unix Utilities","title":"一套有用的 Unix 實用程序","tag":"201808","desc":""},"relativePath":"201808/20180821 A Collection Of More Useful Unix Utilities.md","filePath":"[post].md"}'),r={name:"201808/20180821 A Collection Of More Useful Unix Utilities.md"};function h(g,s,k,u,b,f){const i=p("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="一套有用的-unix-實用程序" tabindex="-1">一套有用的 Unix 實用程序 <a class="header-anchor" href="#一套有用的-unix-實用程序" aria-label="Permalink to “一套有用的 Unix 實用程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/08/Moreutils-720x340.png" alt=""></p><p>我們都瞭解 <ruby>GNU 核心實用程序<rt>GNU Core Utilities</rt></ruby>，所有類 Unix 操作系統都預裝了它們。它們是 GNU 操作系統中與文件、Shell 和 文本處理相關的基礎實用工具。GNU 核心實用程序包括很多日常操作命令，例如 <code>cat</code>、<code>ls</code>、<code>rm</code>、<code>mkdir</code>、<code>rmdir</code>、<code>touch</code>、<code>tail</code> 和 <code>wc</code> 等。除了這些實用程序，還有更多有用的實用程序沒有預裝在類 Unix 操作系統中，它們彙集起來構成了 <code>moreutilis</code> 這個日益增長的集合。<code>moreutils</code> 可以在 GNU/Linux 和包括 FreeBSD，openBSD 及 Mac OS 在內的多種 Unix 類型操作系統上安裝。</p><p>截至到編寫這份指南時， <code>moreutils</code> 提供如下實用程序：</p><ul><li><code>chronic</code> – 運行程序並忽略正常運行的輸出</li><li><code>combine</code> – 使用布爾操作合併文件的行</li><li><code>errno</code> – 查詢 errno 名稱及描述</li><li><code>ifdata</code> – 獲取網絡接口信息，無需解析 <code>ifconfig</code> 的結果</li><li><code>ifne</code> – 在標準輸入非空的情況下運行程序</li><li><code>isutf8</code> – 檢查文件或標準輸入是否採用 UTF-8 編碼</li><li><code>lckdo</code> – 帶鎖運行程序</li><li><code>mispipe</code> – 使用管道連接兩個命令，返回第一個命令的退出狀態</li><li><code>parallel</code> – 同時運行多個任務</li><li><code>pee</code> – 將標準輸入傳遞給多個管道</li><li><code>sponge</code> – 整合標準輸入並寫入文件</li><li><code>ts</code> – 為標準輸入增加時間戳信息</li><li><code>vidir</code> – 使用你默認的文本編輯器操作目錄文件</li><li><code>vipe</code> – 在管道中插入信息編輯</li><li><code>zrun</code> – 自動解壓並將其作為參數傳遞給命令</li></ul><h3 id="在-linux-上安裝-moreutils" tabindex="-1">在 Linux 上安裝 moreutils <a class="header-anchor" href="#在-linux-上安裝-moreutils" aria-label="Permalink to “在 Linux 上安裝 moreutils”">​</a></h3><p>由於 <code>moreutils</code> 已經被打包到多種 Linux 發行版中，你可以使用發行版對應的軟件包管理器安裝 <code>moreutils</code>。</p><p>在 <strong>Arch Linux</strong> 或衍生的 <strong>Antergos</strong> 和 <strong>Manjaro Linux</strong> 上，運行如下命令安裝 <code>moreutils</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S moreutils</span></span></code></pre></div><p>在 <strong>Fedora</strong> 上，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install moreutils</span></span></code></pre></div><p>在 <strong>RHEL</strong>，<strong>CentOS</strong> 和 <strong>Scientific Linux</strong> 上，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install moreutils</span></span></code></pre></div><p>在 <strong>Debian</strong>，<strong>Ubuntu</strong> 和 <strong>Linux Mint</strong> 上，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install moreutils</span></span></code></pre></div><h3 id="moreutils-–-打包更多有用的-unix-實用程序" tabindex="-1">Moreutils – 打包更多有用的 Unix 實用程序 <a class="header-anchor" href="#moreutils-–-打包更多有用的-unix-實用程序" aria-label="Permalink to “Moreutils – 打包更多有用的 Unix 實用程序”">​</a></h3><p>讓我們看一下幾個 <code>moreutils</code> 工具的用法細節。</p><h4 id="combine-實用程序" tabindex="-1">combine 實用程序 <a class="header-anchor" href="#combine-實用程序" aria-label="Permalink to “combine 實用程序”">​</a></h4><p>正如 <code>combine</code> 名稱所示，moreutils 中的這個實用程序可以使用包括 <code>and</code>，<code>not</code>，<code>or</code> 和 <code>xor</code> 在內的布爾操作，合併兩個文件中的行。</p><ul><li><code>and</code> – 輸出 <code>file1</code> 和 <code>file2</code> 都包含的行。</li><li><code>not</code> – 輸出 <code>file1</code> 包含但 <code>file2</code> 不包含的行。</li><li><code>or</code> – 輸出 <code>file1</code> 或 <code>file2</code> 包含的行。</li><li><code>xor</code> – 輸出僅被 <code>file1</code> 或 <code>file2</code> 包含的行</li></ul><p>下面舉例説明，方便你理解該實用程序的功能。這裏有兩個文件，文件名分別為 <code>file1</code> 和 <code>file2</code>，其內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1</span></span>
<span class="line"><span>is</span></span>
<span class="line"><span>was</span></span>
<span class="line"><span>were</span></span>
<span class="line"><span>where</span></span>
<span class="line"><span>there</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat file2</span></span>
<span class="line"><span>is</span></span>
<span class="line"><span>were</span></span>
<span class="line"><span>there</span></span></code></pre></div><p>下面，我使用 <code>and</code> 布爾操作合併這兩個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ combine file1 and file2</span></span>
<span class="line"><span>is</span></span>
<span class="line"><span>were</span></span>
<span class="line"><span>there</span></span></code></pre></div><p>從上例的輸出中可以看出，<code>and</code> 布爾操作只輸出那些 <code>file1</code> 和 <code>file2</code> 都包含的行；更具體的來説，命令輸出為兩個文件共有的行，即 is，were 和 there。</p><p>下面我們換成 <code>not</code> 操作，觀察一下輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ combine file1 not file2</span></span>
<span class="line"><span>was</span></span>
<span class="line"><span>where</span></span></code></pre></div><p>從上面的輸出中可以看出，<code>not</code> 操作輸出 <code>file1</code> 包含但 <code>file2</code> 不包含的行。</p><h4 id="ifdata-實用程序" tabindex="-1">ifdata 實用程序 <a class="header-anchor" href="#ifdata-實用程序" aria-label="Permalink to “ifdata 實用程序”">​</a></h4><p><code>ifdata</code> 實用程序可用於檢查網絡接口是否存在，也可用於獲取網絡接口的信息，例如 IP 地址等。與預裝的 <code>ifconfig</code> 和 <code>ip</code> 命令不同，<code>ifdata</code> 的輸出更容易解析，這種設計的初衷是便於在 Shell 腳本中使用。</p><p>如果希望查看某個接口的 IP 地址，不妨以 <code>wlp9s0</code> 為例，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -p wlp9s0</span></span>
<span class="line"><span>192.168.43.192 255.255.255.0 192.168.43.255 1500</span></span></code></pre></div><p>如果只查看掩碼信息，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -pn wlp9s0</span></span>
<span class="line"><span>255.255.255.0</span></span></code></pre></div><p>如果查看網絡接口的物理地址，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -ph wlp9s0</span></span>
<span class="line"><span>A0:15:46:90:12:3E</span></span></code></pre></div><p>如果判斷接口是否存在，可以使用 <code>-pe</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifdata -pe wlp9s0</span></span>
<span class="line"><span>yes</span></span></code></pre></div><h4 id="pee-命令" tabindex="-1">pee 命令 <a class="header-anchor" href="#pee-命令" aria-label="Permalink to “pee 命令”">​</a></h4><p>該命令某種程度上類似於 <code>tee</code> 命令。</p><p>我們先用一個例子看一下 <code>tee</code> 的用法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Welcome to OSTechNIx&quot; | tee file1 file2</span></span>
<span class="line"><span>Welcome to OSTechNIx</span></span></code></pre></div><p>上述命令首先創建兩個文件，名為 <code>file1</code> 和 <code>file2</code>；接着，將 “Welcome to OSTechNix” 行分別附加到兩個文件中；最後，在終端中打印輸出 “Welcome to OSTechNix”。</p><p><code>pee</code> 命令提供類似的功能，但與 <code>tee</code> 又稍微有些差異。查看下面的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Welcome to OSTechNIx&quot; | pee cat cat</span></span>
<span class="line"><span>Welcome to OSTechNIx</span></span>
<span class="line"><span>Welcome to OSTechNIx</span></span></code></pre></div><p>從上面的命令輸出中可以看出，有兩個 <code>cat</code> 命令實例獲取 <code>echo</code> 命令的輸出並執行，因而終端中出現兩個同樣的輸出。</p><h4 id="sponge-實用程序" tabindex="-1">sponge 實用程序 <a class="header-anchor" href="#sponge-實用程序" aria-label="Permalink to “sponge 實用程序”">​</a></h4><p>這是 <code>moreutils</code> 軟件包中的另一個有用的實用程序。<code>sponge</code> 讀取標準輸入並寫入到指定的文件中。與 Shell 中的重定向不同，<code>sponge</code> 接收到完整輸入後再寫入輸出文件。</p><p>查看下面這個文本文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1</span></span>
<span class="line"><span>I</span></span>
<span class="line"><span>You</span></span>
<span class="line"><span>Me</span></span>
<span class="line"><span>We</span></span>
<span class="line"><span>Us</span></span></code></pre></div><p>可見，文件包含了一些無序的行；更具體的説，這些行“沒有”按照字母順序排序。如果希望將其內容安裝字母順序排序，你會怎麼做呢？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sort file1 &gt; file1_sorted</span></span></code></pre></div><p>這樣做沒錯，對吧？當然沒錯！在上面的命令中，我將 <code>file1</code> 文件內容按照字母順序排序，將排序後的內容保存在 <code>file1_sorted</code> 文件中。但如果使用 <code>sponge</code> 命令，你可以在不創建新文件（即 <code>file1_sorted</code>）的情況下完成同樣的任務，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sort file1 | sponge file1</span></span></code></pre></div><p>那麼，讓我們檢查一下文件內容是否已經按照字母順序排序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1</span></span>
<span class="line"><span>I</span></span>
<span class="line"><span>Me</span></span>
<span class="line"><span>Us</span></span>
<span class="line"><span>We</span></span>
<span class="line"><span>You</span></span></code></pre></div><p>看到了吧？並不需要創建新文件。在腳本編程中，這非常有用。另一個好消息是，如果待寫入的文件已經存在，<code>sponge</code> 會保持其<ruby>權限信息<rt>permissions</rt></ruby>不變。</p><h4 id="ts-實用程序" tabindex="-1">ts 實用程序 <a class="header-anchor" href="#ts-實用程序" aria-label="Permalink to “ts 實用程序”">​</a></h4><p>正如名稱所示，<code>ts</code> 命令在每一行輸出的行首增加<ruby>時間戳<rt>timestamp</rt></ruby>。</p><p>查看如下命令的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 2 localhost</span></span>
<span class="line"><span>PING localhost(localhost.localdomain (::1)) 56 data bytes</span></span>
<span class="line"><span>64 bytes from localhost.localdomain (::1): icmp_seq=1 ttl=64 time=0.055 ms</span></span>
<span class="line"><span>64 bytes from localhost.localdomain (::1): icmp_seq=2 ttl=64 time=0.079 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- localhost ping statistics ---</span></span>
<span class="line"><span>2 packets transmitted, 2 received, 0% packet loss, time 1018ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.055/0.067/0.079/0.012 ms</span></span></code></pre></div><p>下面，結合 <code>ts</code> 實用程序運行同樣地命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 2 localhost | ts</span></span>
<span class="line"><span>Aug 21 13:32:28 PING localhost(localhost (::1)) 56 data bytes</span></span>
<span class="line"><span>Aug 21 13:32:28 64 bytes from localhost (::1): icmp_seq=1 ttl=64 time=0.063 ms</span></span>
<span class="line"><span>Aug 21 13:32:28 64 bytes from localhost (::1): icmp_seq=2 ttl=64 time=0.113 ms</span></span>
<span class="line"><span>Aug 21 13:32:28</span></span>
<span class="line"><span>Aug 21 13:32:28 --- localhost ping statistics ---</span></span>
<span class="line"><span>Aug 21 13:32:28 2 packets transmitted, 2 received, 0% packet loss, time 4ms</span></span>
<span class="line"><span>Aug 21 13:32:28 rtt min/avg/max/mdev = 0.063/0.088/0.113/0.025 ms</span></span></code></pre></div><p>對比輸出可以看出，<code>ts</code> 在每一行行首增加了時間戳。下面給出另一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l | ts</span></span>
<span class="line"><span>Aug 21 13:34:25 total 120</span></span>
<span class="line"><span>Aug 21 13:34:25 drwxr-xr-x 2 sk users 12288 Aug 20 20:05 Desktop</span></span>
<span class="line"><span>Aug 21 13:34:25 drwxr-xr-x 2 sk users 4096 Aug 10 18:44 Documents</span></span>
<span class="line"><span>Aug 21 13:34:25 drwxr-xr-x 24 sk users 12288 Aug 21 13:06 Downloads</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h4 id="vidir-實用程序" tabindex="-1">vidir 實用程序 <a class="header-anchor" href="#vidir-實用程序" aria-label="Permalink to “vidir 實用程序”">​</a></h4><p><code>vidir</code> 實用程序可以讓你使用 <code>vi</code> 編輯器（或其它 <code>$EDITOR</code> 環境變量指定的編輯器）編輯指定目錄的內容。如果沒有指定目錄，<code>vidir</code> 會默認編輯你當前的目錄。</p><p>下面的命令編輯 <code>Desktop</code> 目錄的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vidir Desktop/</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/sk@sk_001-1.png" alt="vidir"></p><p>上述命令使用 <code>vi</code> 編輯器打開了指定的目錄，其中目錄內的文件都會對應一個數字。下面你可以按照 <code>vi</code> 的操作方式來編輯目錄中的這些文件：例如，刪除行意味着刪除目錄中對應的文件，修改行中字符串意味着對文件進行重命名。</p><p>你也可以編輯子目錄。下面的命令會編輯當前目錄及所有子目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find | vidir -</span></span></code></pre></div><p>請注意命令結尾的 <code>-</code>。如果 <code>-</code> 被指定為待編輯的目錄，<code>vidir</code> 會從標準輸入讀取一系列文件名，列出它們讓你進行編輯。</p><p>如果你只想編輯當前目錄下的文件，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -type f | vidir -</span></span></code></pre></div><p>只想編輯特定類型的文件，例如 <code>.PNG</code> 文件？你可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vidir *.png</span></span></code></pre></div><p>這時命令只會編輯當前目錄下以 <code>.PNG</code> 為後綴的文件。</p><h4 id="vipe-實用程序" tabindex="-1">vipe 實用程序 <a class="header-anchor" href="#vipe-實用程序" aria-label="Permalink to “vipe 實用程序”">​</a></h4><p><code>vipe</code> 命令可以讓你使用默認編輯器接收 Unix 管道輸入，編輯之後使用管道輸出供下一個程序使用。</p><p>執行下面的命令會打開 <code>vi</code> 編輯器（當然是我默認使用的編輯器），你可以編輯 <code>echo</code> 命令的管道輸入（即 “Welcome to OSTechNix”），最後將編輯過的內容輸出到終端中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Welcome to OSTechNIx&quot; | vipe</span></span>
<span class="line"><span>Hello World</span></span></code></pre></div><p>從上面的輸出可以看出，我通過管道將 “Welcome to OSTechNix” 輸入到 <code>vi</code> 編輯器中，將內容編輯為 “Hello World”，最後顯示該內容。</p><p>好了，就介紹這麼多吧。我只介紹了一小部分實用程序，而 <code>moreutils</code> 包含更多有用的實用程序。我在文章開始的時候已經列出目前 <code>moreutils</code> 軟件包內包含的實用程序，你可以通過 <code>man</code> 幫助頁面獲取更多相關命令的細節信息。舉個例子，如果你想了解 <code>vidir</code> 命令，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man vidir</span></span></code></pre></div><p>希望這些內容對你有所幫助。我還將繼續分享其它有趣且實用的指南，如果你認為這些內容對你有所幫助，請分享到社交網絡或專業圈子，也歡迎你支持 OSTechNix 項目。</p><p>乾杯！</p><hr>`,89)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.ostechnix.com/moreutils-collection-useful-unix-utilities/"},{default:n(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/moreutils-collection-useful-unix-utilities/",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=e("作者：",-1)),a(i,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(i,{href:"https://github.com/pinewall"},{default:n(()=>[...s[4]||(s[4]=[e("pinewall",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const v=t(r,[["render",h]]);export{y as __pageData,v as default};
